// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK, LogFile} from "../src/DEP_BANK.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    DEP_BANK c;
    function setUp() public { c = new DEP_BANK(); }

    function testFuzz_property(uint256 depositAmount, uint256 collectAmount) public {
        vm.assume(depositAmount <= VALUE_CAP);
        // WIDE admissible domain: caller must be able to deposit and then collect.
        depositAmount = bound(depositAmount, 0, type(uint128).max);
        collectAmount = bound(collectAmount, 0, depositAmount);

        // Deploy a recording LogFile so both P and M can reach their happy path.
        LogFile log = new LogFile();
        c.SetLogFile(address(log));
        c.SetMinSum(0);
        c.Initialized();

        address actor = address(uint160(uint256(keccak256(abi.encode(depositAmount, collectAmount)))));
        vm.deal(actor, depositAmount + collectAmount);

        // Record the caller's balance before Collect, then perform the deposit and collect.
        vm.startPrank(actor);
        c.Deposit{value: depositAmount}();
        uint256 beforeBalance = c.balances(actor);
        uint256 beforeContractBalance = address(c).balance;
        vm.stopPrank();

        vm.prank(actor);
        c.Collect{value: 0}(collectAmount);

        uint256 afterBalance = c.balances(actor);
        uint256 afterContractBalance = address(c).balance;
        uint256 actualPayout = beforeContractBalance - afterContractBalance;

        // GENERAL RULE: the ETH leaving C must equal the decrease in the caller's tracked balance.
        // P: beforeBalance - afterBalance == actualPayout (balance is debited by _am, payout is _am).
        // M: afterBalance == beforeBalance (never debited) while actualPayout == _am, so equality breaks.
        assertTrue(beforeBalance - afterBalance == actualPayout);
    }
}
